import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type SadFacePostProps = Record<string, any>;

const HeartIcon: React.FC<{ color: string; scale: number }> = ({ color, scale }) => (
  <svg
    viewBox="0 0 24 24"
    style={{
      width: "100%",
      height: "100%",
      fill: color,
      transform: `scale(${scale})`,
      transformOrigin: "center bottom",
    }}
  >
    <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
  </svg>
);

const SadFacePost: React.FC<SadFacePostProps> = ({
  backgroundColor = "#f3f4f6",
  transparentBackground = false,
  durationInSeconds = 6,
  faceColor = "#e5e7eb",
  featureColor = "#4b5563",
  panelColor = "#ffffff",
  heartColor = "#ef4444",
  textColor = "#1f2937",
  maxLikes = 3,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // --- Animation Timing ---
  const entranceDelay = 5;
  const likeStartFrame = 45;
  const disappointmentFrame = 110;

  // --- Entrance (Spring) ---
  const entranceSpring = spring({
    frame: frame - entranceDelay,
    fps,
    config: { damping: 14, stiffness: 80 },
  });

  const contentOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // --- The Hesitant Like Counter ---
  // Ticks: 0 -> 1 (fast), 1 -> 2 (slow pause), 2 -> 3 (stop)
  // We manually craft the "hesitant" feel using keyframes
  const likeProgress = interpolate(
    frame,
    [likeStartFrame, likeStartFrame + 10, likeStartFrame + 40, likeStartFrame + 50, likeStartFrame + 90],
    [0, 1, 1, 2, maxLikes > 2 ? 3 : maxLikes], // Cap at 3 for "low engagement" effect usually
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );
  
  const currentLikes = Math.floor(likeProgress);

  // Heart Beat on change
  const heartBeat = spring({
    frame: frame - (frame > likeStartFrame + 50 ? likeStartFrame + 50 : likeStartFrame),
    fps,
    config: { damping: 10, stiffness: 200 },
    durationInFrames: 10
  });
  
  // Logic to trigger heartbeat only when number changes (simplified via modulo approximation for visuals)
  const isChanging = frame === likeStartFrame || frame === likeStartFrame + 50;
  const heartScale = isChanging ? 1.3 : 1; 
  // Smooth out the immediate scale
  const heartScaleSmoothed = spring({
    frame: frame - (isChanging ? frame : -100),
    fps,
    config: { stiffness: 300, damping: 15 }
  });
  
  const activeHeartScale = 1 + (heartScaleSmoothed * 0.3);


  // --- The Disappointment Reaction ---
  const reactionProgress = spring({
    frame: frame - disappointmentFrame,
    fps,
    config: { damping: 20, stiffness: 40, mass: 2 }, // Heavy, slow movement
  });

  // Shoulders drop
  const shoulderY = interpolate(reactionProgress, [0, 1], [0, 40]);
  
  // Face Sinking (slight scale down and move down)
  const faceY = interpolate(reactionProgress, [0, 1], [0, 25]);
  
  // Mouth Frown Increase (Control point of Bezier curve)
  // Initial sad mouth: Quadratic bezier. 
  // Anchor points: (60, 130), (140, 130). Control point starts at (100, 110) and moves to (100, 100)
  const mouthControlY = interpolate(reactionProgress, [0, 1], [115, 95]); 

  // Eyes "Drooping" (Rotate slightly outwards/downwards)
  const eyeRotation = interpolate(reactionProgress, [0, 1], [0, 15]);


  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <AbsoluteFill
        style={{
            display: "flex",
            flexDirection: "row",
            justifyContent: "center",
            alignItems: "center",
            gap: 60,
            opacity: contentOpacity,
            transform: `translateY(${(1 - entranceSpring) * 50}px)`,
        }}
      >
        {/* --- CHARACTER / FACE --- */}
        <div style={{ position: "relative", width: 300, height: 400 }}>
            <svg width="300" height="400" viewBox="0 0 200 250">
                {/* Shoulders */}
                <path 
                    d="M 20,250 Q 100,180 180,250 L 180,300 L 20,300 Z" 
                    fill={faceColor} 
                    transform={`translate(0, ${shoulderY})`}
                />
                
                {/* Head Group */}
                <g transform={`translate(0, ${faceY})`}>
                    {/* Face Shape */}
                    <ellipse cx="100" cy="100" rx="70" ry="85" fill={faceColor} />
                    
                    {/* Eyes - Left */}
                    <g transform={`rotate(${-eyeRotation}, 75, 90)`}>
                        <ellipse cx="75" cy="90" rx="6" ry="9" fill={featureColor} />
                        {/* Eyebrow/lid hint for sadness */}
                        <path d="M 65,85 Q 75,82 85,85" stroke={featureColor} strokeWidth="2" fill="none" />
                    </g>

                    {/* Eyes - Right */}
                    <g transform={`rotate(${eyeRotation}, 125, 90)`}>
                        <ellipse cx="125" cy="90" rx="6" ry="9" fill={featureColor} />
                        <path d="M 115,85 Q 125,82 135,85" stroke={featureColor} strokeWidth="2" fill="none" />
                    </g>

                    {/* Mouth - Animated Bezier */}
                    {/* Sad mouth is an arc curving upwards in the middle (coordinates relative to SVG) */}
                    <path 
                        d={`M 70,140 Q 100,${mouthControlY} 130,140`} 
                        stroke={featureColor} 
                        strokeWidth="4" 
                        fill="none" 
                        strokeLinecap="round"
                    />
                </g>
            </svg>
        </div>

        {/* --- PHONE PANEL --- */}
        <div
            style={{
                width: 220,
                height: 380,
                backgroundColor: panelColor,
                borderRadius: 24,
                boxShadow: "0 10px 30px rgba(0,0,0,0.1)",
                display: "flex",
                flexDirection: "column",
                padding: 24,
                justifyContent: "flex-end",
            }}
        >
            {/* Fake Content Placeholders */}
            <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 12 }}>
                <div style={{ width: '100%', height: '60%', backgroundColor: `${featureColor}15`, borderRadius: 12 }} />
                <div style={{ width: '80%', height: 12, backgroundColor: `${featureColor}15`, borderRadius: 6 }} />
                <div style={{ width: '60%', height: 12, backgroundColor: `${featureColor}15`, borderRadius: 6 }} />
            </div>

            {/* Like Bar */}
            <div style={{ 
                height: 60, 
                display: "flex", 
                alignItems: "center", 
                gap: 12,
                marginTop: 20,
                borderTop: `1px solid ${featureColor}15`,
                paddingTop: 16
            }}>
                <div style={{ width: 32, height: 32 }}>
                    <HeartIcon color={heartColor} scale={activeHeartScale} />
                </div>
                <div style={{ 
                    fontSize: 24, 
                    fontWeight: 700, 
                    color: textColor,
                    fontVariantNumeric: "tabular-nums" 
                }}>
                    {currentLikes}
                </div>
            </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default SadFacePost;